{
 "episodeSummary": "James P. Whitfield, Ventricular Tachycardia, critical, hemodynamically borderline (BP 88/58)",
 "rhythm": "Ventricular Tachycardia (VT)",
 "keyECGEvidence": [
  "ventricularRateBpm 182",
  "qrsDurationMs 168",
  "AV dissociation",
  "Wide monomorphic QRS",
  "occasional capture/fusion beats"
 ],
 "primaryEtiology": "Acute myocardial ischemia/demand ischemia in the setting of decompensated ischemic cardiomyopathy",
 "mechanism": "Re-entry within the ventricular myocardium due to structural scarring and acute myocardial demand ischemia",
 "contributingFactors": [
  "Decompensated ischemic cardiomyopathy (LVEF 25%)",
  "Troponin T 0.09 ng/mL mildly HIGH (demand)",
  "BNP 1840 pg/mL HIGH",
  "CKD stage 3 (Creatinine 1.9 mg/dL HIGH)"
 ],
 "rejectedAlternatives": [
   {
    "alternative": "Torsades de Pointes",
    "why": "Rhythm is monomorphic with AV dissociation rather than polymorphic; baseline QTc 460 ms is not significantly prolonged."
   },
   {
    "alternative": "Supraventricular Tachycardia with aberrancy",
    "why": "Presence of AV dissociation and fusion beats confirms a ventricular origin."
   },
   {
    "alternative": "Electrolyte-induced arrhythmia (Hypokalemia/Hypomagnesemia)",
    "why": "K 4.3 mmol/L and Mg 2.1 mg/dL are within normal limits."
   }
 ]
 ],
 "recommendedActions": [
  "Assess for immediate cardioversion if blood pressure deteriorates further (patient is currently borderline at 88/58)",
  "Administer Amiodarone or Lidocaine per ACLS protocol for stable/borderline VT",
  "Evaluate for acute coronary syndrome (ACS) via serial troponins and urgent cardiology consultation",
  "Optimize volume status; monitor renal function (Creatinine 1.9 mg/dL HIGH) and electrolyte trends",
  "Continue continuous cardiac monitoring and prepare for potential ICD/PPM evaluation"
 ],
 "uncertainty": [
  "The exact trigger for the acute rise in troponin (demand vs. acute coronary event) cannot be definitively distinguished without serial labs."
 ]
}

